Nguồn địa điểm bản đồ, chưa Sales ghé hoặc xác minh cửa hàng còn hoạt động năm 2026."},{"district":"Huyện Thạnh Trị","name":"Nhà sách Ngọc Thanh","address_line":"23 Quốc lộ 1, thị trấn Phú Lộc cũ, huyện Thạnh Trị","category":"nha_sach","phone":null,"tax_code":null,"source_key":"contact:ngocthanh:23-ql1-phuloc","source_url":"https://vn-vi391530-nha-sa-ch-ngo-c-thanh.contact.page/","verification_note":"Nguồn danh bạ có số 23 QL1 nhưng chưa có điện thoại, cần xác minh có phải cơ sở khác Nhà sách Thanh Tâm."},{"district":"Thị xã Vĩnh Châu","name":"Hiệu sách - Photo Tú Loan","address_line":"7 Trưng Nhị, TX Vĩnh Châu cũ","category":"nha_sach","phone":"02993861029","tax_code":null,"source_key":"gmap:ChIJZekIiMW6oTERujvvopXV3CI","source_url":"https://www.google.com/maps/search/?api=1&query=Hi%E1%BB%87u%20s%C3%A1ch%20-%20Photo%20T%C3%BA%20Loan%207%20Tr%C6%B0ng%20Nh%E1%BB%8B%2C%20TX%20V%C4%A9nh%20Ch%C3%A2u%20c%C5%A9%20S%C3%B3c%20Tr%C4%83ng&query_place_id=ChIJZekIiMW6oTERujvvopXV3CI","verification_note":"Nguồn địa điểm bản đồ, chưa Sales ghé hoặc xác minh cửa hàng còn hoạt động năm 2026."},{"district":"Thị xã Vĩnh Châu","name":"Nhà sách VPP Gia Hân","address_line":"217 Đồng Khởi, TX Vĩnh Châu cũ","category":"nha_sach","phone":"0944900222","tax_code":null,"source_key":"gmap:ChIJQXBq4h67oTERrcqb9Z1Nwf4","source_url":"https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20s%C3%A1ch%20VPP%20Gia%20H%C3%A2n%20217%20%C4%90%E1%BB%93ng%20Kh%E1%BB%9Fi%2C%20TX%20V%C4%A9nh%20Ch%C3%A2u%20c%C5%A9%20S%C3%B3c%20Tr%C4%83ng&query_place_id=ChIJQXBq4h67oTERrcqb9Z1Nwf4","verification_note":"Nguồn địa điểm bản đồ, chưa Sales ghé hoặc xác minh cửa hàng còn hoạt động năm 2026."}]'::jsonb) AS x(
 district text,name text,address_line text,category text,phone text,tax_code text,source_key text,source_url text,verification_note text)),
 ins AS(INSERT INTO public.field_prospects(id,area_visit_id,owner_sub,name,address_line,province,district,category,phone,tax_code,note,status,source_kind,research_source_key,research_source_url,research_batch)
 SELECT (substr(s.dg,1,8)||'-'||substr(s.dg,9,4)||'-5'||substr(s.dg,14,3)||'-8'||substr(s.dg,18,3)||'-'||substr(s.dg,21,12))::uuid,
 NULL,'ef943de4-18f7-49ef-8340-eefb18855534',s.name,s.address_line,'Sóc Trăng',s.district,s.category,s.phone,s.tax_code,
 'Nguồn công khai 21/11/2026; CHƯA GHÉ; GPS chưa xác minh; tình trạng bán lẻ chưa xác minh. '||s.verification_note||' Nguồn: '||s.source_url,
 'new','manual',s.source_key,s.source_url,'2026-11-21-soc-trang-old-wave-03'
 FROM src s WHERE s.district IN ('Huyện Thạnh Trị','Thị xã Vĩnh Châu','Huyện Trần Đề') AND s.source_url LIKE 'https://%'
 AND NOT EXISTS(SELECT 1 FROM customers c WHERE c.province='Sóc Trăng' AND c.district=s.district AND
 (lower(trim(c.name))=lower(trim(s.name)) OR (c.phone IS NOT NULL AND s.phone IS NOT NULL AND c.phone=s.phone)))
 AND NOT EXISTS(SELECT 1 FROM field_prospects p WHERE p.province='Sóc Trăng' AND p.district=s.district AND
 (p.research_source_key=s.source_key OR (lower(trim(p.name))=lower(trim(s.name)) AND lower(trim(p.address_line))=lower(trim(s.address_line)))
 OR (p.phone IS NOT NULL AND s.phone IS NOT NULL AND p.phone=s.phone) OR (p.tax_code IS NOT NULL AND s.tax_code IS NOT NULL AND p.tax_code=s.tax_code)))
 ON CONFLICT(research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING RETURNING district,category,phone)
 SELECT district,count(*)::int inserted,count(*) FILTER(WHERE category='nha_sach')::int bookstores FROM ins GROUP BY district ORDER BY district;